import java.util.*;

class Solution {
    public int[] maximumWeight(List<List<Integer>> intervals) {
            int n = intervals.size();
                    Integer[] order = new Integer[n];
                            for (int i = 0; i < n; i++) order[i] = i;
                                    Arrays.sort(order, Comparator.comparingInt(i -> intervals.get(i).get(1)));

                                            // Store non-overlapping predecessor index for each sorted interval
                                                    int[] prev = new int[n];
                                                            for (int i = 0; i < n; i++) {
                                                                        int l = intervals.get(order[i]).get(0);
                                                                                    int low = 0, high = i - 1, ans = -1;
                                                                                                while (low <= high) {
                                                                                                                int mid = (low + high) / 2;
                                                                                                                                if (intervals.get(order[mid]).get(1) < l) { ans = mid; low = mid + 1; }
                                                                                                                                                else high = mid - 1;
                                                                                                                                                            }
                                                                                                                                                                        prev[i] = ans;
                                                                                                                                                                                }

                                                                                                                                                                                        // DP state: dp[k][i] = {max_weight, indices_array}
                                                                                                                                                                                                long[][] weight = new long[5][n + 1];
                                                                                                                                                                                                        int[][][] indices = new int[5][n + 1][];

                                                                                                                                                                                                                for (int k = 1; k <= 4; k++) {
                                                                                                                                                                                                                            for (int i = 1; i <= n; i++) {
                                                                                                                                                                                                                                            int orig = order[i - 1];
                                                                                                                                                                                                                                                            long w = intervals.get(orig).get(2);
                                                                                                                                                                                                                                                                            int p = prev[i - 1] + 1;

                                                                                                                                                                                                                                                                                            // Option 1: Exclude
                                                                                                                                                                                                                                                                                                            weight[k][i] = weight[k][i - 1];
                                                                                                                                                                                                                                                                                                                            indices[k][i] = indices[k][i - 1];

                                                                                                                                                                                                                                                                                                                                            // Option 2: Include
                                                                                                                                                                                                                                                                                                                                                            long newWeight = weight[k - 1][p] + w;
                                                                                                                                                                                                                                                                                                                                                                            int[] prevIdxs = indices[k - 1][p] == null ? new int[0] : indices[k - 1][p];
                                                                                                                                                                                                                                                                                                                                                                                            int[] newIndices = Arrays.copyOf(prevIdxs, prevIdxs.length + 1);
                                                                                                                                                                                                                                                                                                                                                                                                            newIndices[newIndices.length - 1] = orig;
                                                                                                                                                                                                                                                                                                                                                                                                                            Arrays.sort(newIndices);

                                                                                                                                                                                                                                                                                                                                                                                                                                            if (newWeight > weight[k][i] || (newWeight == weight[k][i] && compare(newIndices, indices[k][i]))) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                weight[k][i] = newWeight;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    indices[k][i] = newIndices;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int[] best = new int[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        long maxW = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (int k = 1; k <= 4; k++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (weight[k][n] > maxW || (weight[k][n] == maxW && compare(indices[k][n], best))) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            maxW = weight[k][n];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            best = indices[k][n];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return best == null ? new int[0] : best;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                private boolean compare(int[] a, int[] b) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (b == null) return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (a == null) return false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (int i = 0; i < Math.min(a.length, b.length); i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (a[i] != b[i]) return a[i] < b[i];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return a.length <= b.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }